const visible=(q,a)=> (!q.when || [a[q.when[0]]].flat().includes(q.when[1])) && (!q.unless || (a[q.unless[0]] && ![a[q.unless[0]]].flat().includes(q.unless[1])));
const answered=v=>Array.isArray(v)?v.length>0:typeof v==='string'&&v.trim().length>0;
function validate(q,v){if(q.required&&!answered(v))return '回答してください';if(!answered(v))return '';if(['single','multi','design'].includes(q.type)){const opts=q.type==='design'?['白基調','ダーク','ナチュラル','高級感','シンプル','ポップ']:q.options;if(![v].flat().every(x=>opts.includes(x)))return '選択肢を確認してください';}if(q.type==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))return 'メール形式を確認してください';if(q.type==='url'){try{if(!['https:','http:'].includes(new URL(v).protocol))return 'https または http のURLを入力してください'}catch{return 'URLを確認してください'}}return '';}
function payload(schema,a,notes,id,project){return {submissionId:id,projectId:project,schemaVersion:schema.version,answers:schema.questions.filter(q=>visible(q,a)).map(q=>({questionId:q.id,answer:a[q.id]??(q.type==='multi'?[]:''),note:notes[q.id]??''}))};}

const ID=/^[-a-zA-Z0-9]{3,80}$/;
function registry(env){
  const r=JSON.parse(env.ACCESS_REGISTRY||'{"version":1,"grants":[]}');
  if(r.version!==1||!Array.isArray(r.grants)||r.grants.length>2000)throw Error('access_configuration');
  const seen=new Set();
  for(const g of r.grants){
    if(!g||!ID.test(g.projectId)||!ID.test(g.userId)||typeof g.enabled!=='boolean'||!Number.isFinite(Date.parse(g.expiresAt))||seen.has(g.userId+'|'+g.projectId))throw Error('access_configuration');
    seen.add(g.userId+'|'+g.projectId);
  }
  return r;
}
function principal(request,env,projectId,now=Date.now()){
  const userId=request.headers.get('oai-authenticated-user-id');
  if(!userId)return {status:401,error:'authentication_required'};
  const operators=(env.OPERATOR_IDS||'').split(',').filter(Boolean);
  let r;try{r=registry(env)}catch{return {status:503,error:'access_configuration'}}
  const isOperator=operators.includes(userId);
  if(env.DEPLOYMENT_MODE==='review'){
    // This branch is only permitted on an owner-private Sites deployment.
    if(env.REVIEW_OWNER_ONLY_CONFIRMED!=='true')return {status:503,error:'review_boundary_not_confirmed'};
    if(projectId&&projectId!=='QA-V11-OWNER')return {status:403,error:'project_forbidden'};
    return {userId,role:isOperator?'operator':'review',projectId:'QA-V11-OWNER',projects:['QA-V11-OWNER'],expiresAt:null,review:true};
  }
  if(env.DEPLOYMENT_MODE!=='clients'||env.CLIENT_RELEASE_APPROVED!=='true')return {status:403,error:'client_release_not_approved'};
  const active=r.grants.filter(g=>g.userId===userId&&g.enabled&&Date.parse(g.expiresAt)>now);
  const g=projectId?active.find(g=>g.projectId===projectId):active.length===1?active[0]:null;
  if(!g)return {status:403,error:active.length>1&&!projectId?'project_selection_required':'project_forbidden',projects:active.map(g=>g.projectId)};
  return {userId,role:isOperator?'operator':'client',projectId:g.projectId,projects:active.map(g=>g.projectId),expiresAt:g.expiresAt,review:false};
}
async function storageId(projectId,id){
  const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(projectId+'\0'+id));
  return 'V11-'+[...new Uint8Array(bytes)].map(b=>b.toString(16).padStart(2,'0')).join('');
}
async function readBounded(request,limit=400000){
  if(Number(request.headers.get('content-length'))>limit)throw Error('payload_too_large');
  if(!request.body)return '';
  const reader=request.body.getReader(),parts=[];let size=0;
  while(true){const {value,done}=await reader.read();if(done)break;size+=value.byteLength;if(size>limit){await reader.cancel();throw Error('payload_too_large')}parts.push(value)}
  const all=new Uint8Array(size);let n=0;for(const b of parts){all.set(b,n);n+=b.length}return new TextDecoder('utf-8',{fatal:true}).decode(all);
}

const LINK_COOKIE='__Host-alopex-client';
async function hashToken(token){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token)))].map(x=>x.toString(16).padStart(2,'0')).join('')}
function linkRegistry(env){
 const r=JSON.parse(env.CLIENT_LINKS||'{"version":1,"links":[]}');
 if(r.version!==1||!Array.isArray(r.links)||r.links.length>2000)throw Error('link_configuration');
 const seen=new Set();for(const l of r.links){if(!l||!/^[a-f0-9]{64}$/.test(l.tokenHash)||!/^[-a-zA-Z0-9]{3,80}$/.test(l.projectId)||typeof l.enabled!=='boolean'||!Number.isFinite(Date.parse(l.expiresAt))||seen.has(l.tokenHash))throw Error('link_configuration');seen.add(l.tokenHash)}return r.links;
}
async function signature(value,secret){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);return [...new Uint8Array(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(value)))].map(x=>x.toString(16).padStart(2,'0')).join('')}
function timingEqual(a,b){if(typeof a!=='string'||typeof b!=='string'||a.length!==b.length)return false;let n=0;for(let i=0;i<a.length;i++)n|=a.charCodeAt(i)^b.charCodeAt(i);return n===0}
async function exchangeLink(token,env,now=Date.now()){
 if(env.CLIENT_LINKS_ENABLED!=='true'||!env.ACCESS_COOKIE_SECRET||env.ACCESS_COOKIE_SECRET.length<32)return {status:503,error:'link_configuration'};
 if(typeof token!=='string'||!/^[a-f0-9]{64}$/.test(token))return {status:403,error:'link_invalid'};
 let links;try{links=linkRegistry(env)}catch{return {status:503,error:'link_configuration'}}
 const hash=await hashToken(token),l=links.find(l=>timingEqual(l.tokenHash,hash)&&l.enabled&&Date.parse(l.expiresAt)>now);
 if(!l)return {status:403,error:'link_invalid'};
 const expires=Math.min(Math.floor(Date.parse(l.expiresAt)/1000),Math.floor(now/1000)+86400),value='v1.'+hash+'.'+expires;
 const cookie=value+'.'+await signature(value,env.ACCESS_COOKIE_SECRET);
 return {projectId:l.projectId,expiresAt:l.expiresAt,cookie:LINK_COOKIE+'='+cookie+'; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age='+Math.max(0,expires-Math.floor(now/1000))};
}
async function clientPrincipal(request,env,projectId,now=Date.now()){
 if(env.DEPLOYMENT_MODE!=='token_clients')return principal(request,env,projectId,now);
 const uid=request.headers.get('oai-authenticated-user-id');
 if(uid&&(env.OPERATOR_IDS||'').split(',').includes(uid)&&(!projectId||projectId==='QA-V11-OWNER')&&!request.headers.get('Cookie')?.includes(LINK_COOKIE+'='))return {userId:uid,role:'operator',projectId:'QA-V11-OWNER',projects:['QA-V11-OWNER'],expiresAt:null,review:true};
 if(env.CLIENT_LINKS_ENABLED!=='true'||env.CLIENT_RELEASE_APPROVED!=='true'||!env.ACCESS_COOKIE_SECRET||env.ACCESS_COOKIE_SECRET.length<32)return {status:503,error:'link_configuration'};
 const raw=request.headers.get('Cookie')?.split(';').map(x=>x.trim()).find(x=>x.startsWith(LINK_COOKIE+'='))?.slice(LINK_COOKIE.length+1);
 if(!raw||!/^v1\.[a-f0-9]{64}\.[0-9]{10}\.[a-f0-9]{64}$/.test(raw))return {status:401,error:'client_link_required'};
 const [v,hash,exp,sig]=raw.split('.');if(Number(exp)*1000<=now||!timingEqual(sig,await signature(v+'.'+hash+'.'+exp,env.ACCESS_COOKIE_SECRET)))return {status:403,error:'link_invalid'};
 let links;try{links=linkRegistry(env)}catch{return {status:503,error:'link_configuration'}}
 const l=links.find(l=>timingEqual(l.tokenHash,hash)&&l.enabled&&Date.parse(l.expiresAt)>now);
 if(!l||projectId&&l.projectId!==projectId)return {status:403,error:'project_forbidden'};
 return {userId:'link-'+hash.slice(0,24),role:'client',projectId:l.projectId,projects:[l.projectId],expiresAt:l.expiresAt,review:false};
}

